    #[test]
    fn migration_bodies_are_stripped_and_nothing_else() {
        let mut m = sample_manifest();
        m.migrations = vec![
            SqlMigration {
                version: 1,
                name: "initial_tables".into(),
                sql: "CREATE TABLE notes ();".into(),
                no_transaction: false,
            },
            SqlMigration {
                version: 6,
                name: "add_loan_kind".into(),
                sql: "-- cufflink:no-transaction\nSELECT 1;".into(),
                no_transaction: true,
            },
        ];
        let stripped = m.clone().without_migration_bodies();
        assert!(stripped.migrations.iter().all(|m| m.sql.is_empty()));
        let shape = |m: &ServiceManifest| -> Vec<(u32, String, bool)> {
            m.migrations
                .iter()
                .map(|m| (m.version, m.name.clone(), m.no_transaction))
                .collect()
        };
        assert_eq!(shape(&stripped), shape(&m));
        assert_eq!(stripped.name, m.name);
        assert_eq!(stripped.tables.len(), m.tables.len());
    }

