    #[test]
    fn schema_ownership_changes_the_schema_hash_only_when_set() {
        let base = sample_manifest();
        let hash = |m: &ServiceManifest| m.schema_hash().expect("schema hash");
        let changed: Vec<ServiceManifest> = vec![
            ServiceManifest {
                schema: SchemaOwnership::Adopted,
                ..base.clone()
            },
            ServiceManifest {
                schema_name: Some("notes".into()),
                ..base.clone()
            },
            ServiceManifest {
                migrations: vec![SqlMigration {
                    version: 1,
                    name: "a".into(),
                    sql: "SELECT 1;".into(),
                    no_transaction: false,
                }],
                ..base.clone()
            },
            ServiceManifest {
                migration_history: Some(MigrationHistory::default()),
                ..base.clone()
            },
        ];
        let hashes: std::collections::BTreeSet<String> = changed.iter().map(hash).collect();
        assert_eq!(hashes.len(), changed.len());
        assert!(!hashes.contains(&hash(&base)));
    }

