    #[test]
    fn a_reader_without_the_key_sees_no_private_table() {
        let mut m = sample_manifest();
        m.private_tables = vec![private("notes")];
        let mut wire = serde_json::to_value(&m).unwrap();
        assert_eq!(wire["private_tables"][0]["name"], "notes");
        wire.as_object_mut().unwrap().remove("private_tables");
        let older: ServiceManifest = serde_json::from_value(wire).unwrap();
        assert!(older.private_tables.is_empty());
        assert!(older.get_table("notes").is_none());
        assert_eq!(older.declared_tables().count(), 1);
    }

    #[test]
    fn private_tables_join_the_schema_hash_last_and_only_when_declared() {
        use sha2::{Digest, Sha256};
        let base = sample_manifest();
        let mut declaring = base.clone();
        declaring.private_tables = vec![private("notes")];
        let parts = |m: &ServiceManifest| {
            [
                serde_json::to_string(&m.tables).unwrap(),
                serde_json::to_string(&m.custom_routes).unwrap(),
                serde_json::to_string(&m.subscriptions).unwrap(),
                serde_json::to_string(&m.authorization).unwrap(),
                serde_json::to_string(&m.on_migrate).unwrap(),
            ]
            .concat()
        };
        let hash = |text: String| hex::encode(Sha256::digest(text));
        assert_eq!(base.schema_hash().unwrap(), hash(parts(&base)));
        assert_eq!(
            declaring.schema_hash().unwrap(),
            hash(parts(&declaring) + &serde_json::to_string(&declaring.private_tables).unwrap())
        );
        let mut moved = declaring.clone();
        moved.private_tables[0].name = "memos".into();
        assert_ne!(
            moved.schema_hash().unwrap(),
            declaring.schema_hash().unwrap()
        );
    }
